package scope

import (
	"bytes"
	"encoding/json"
	"io"
	"os"
	"path"
	"regexp"
	"strings"
)

// Decision D6' (round 4). A file is left out of an analyzer's scope only on
// deterministic, auditable evidence that it is generated, minified, a vendored
// library or a lockfile, read from its CONTENT, never from its name or its
// directory alone. A file called app.min.js that is ordinary source, a
// directory called vendor/ that holds the project's own code, and a file called
// package-lock.json that is not a lockfile are all in scope. When the evidence
// is not there, the file is uncertain, and uncertain files are in scope.
//
// ClassifyFile reads at most headBytes from the start of a file (and tailBytes
// from its end), and a whole lockfile or source map up to maxParseBytes. The
// evidence kinds, in the order they are checked:
//
//   - lockfile: the exact file name of a package manager's lockfile AND content
//     that parses as that lockfile's format (lockfiles below).
//   - source map: a *.map file whose content is a version-3 source map.
//   - minified: measured from the content (minified below), for JavaScript,
//     TypeScript and CSS.
//   - vendored library: a known library (vendorLibraries) identified by a
//     leading banner whose subject is that library with a version, by the
//     library's own identifier in the body, and by a library's size; never a
//     banner that only mentions a library or any /*! banner.
//   - generated: a generator header (generatedHeader): Go's "Code generated ...
//     DO NOT EDIT.", "@generated", the protobuf compiler's, "do not edit" next
//     to "generated", "Generated by <tool> <version>".
//   - compiled output: a trailing //# sourceMappingURL= comment, or a webpack
//     bootstrap, which a compiler or bundler writes and a person does not.
//
// The thresholds were measured on real code (see the notes in minified).

// Reason names why a file or directory is declared out of scope. The set is
// closed and carries no repository text, so a detail that names a reason can
// never be shaped by the scanned tree.
type Reason string

// File reasons.
const (
	ReasonLockfile  Reason = "lockfile"
	ReasonSourceMap Reason = "source map"
	ReasonMinified  Reason = "minified"
	ReasonVendored  Reason = "vendored library"
	ReasonGenerated Reason = "generator header"
	ReasonCompiled  Reason = "compiled output"
	ReasonTestPath  Reason = "test/fixture path"
	ReasonSymlink   Reason = "symbolic link"
	// ReasonNotChosen is no longer used by an analyzer: a file is never declared
	// out of scope by its extension (decision D6', redteam4-d6-02). Kept so a
	// caller that names it still compiles.
	ReasonNotChosen   Reason = "extension not selected"
	ReasonGenArtifact Reason = "generated artifact" // legacy name-only hint, see Generated
)

// Directory reasons: the evidence found in the directory itself.
const (
	ReasonNPMInstall    Reason = "installed npm packages"
	ReasonPythonVenv    Reason = "python virtualenv"
	ReasonPythonInstall Reason = "installed python packages"
	ReasonGoVendor      Reason = "go vendor tree"
	ReasonComposer      Reason = "composer vendor tree"
	ReasonCargoTarget   Reason = "cargo build output"
	ReasonMavenTarget   Reason = "maven build output"
	ReasonGradleBuild   Reason = "gradle build output"
	ReasonNextBuild     Reason = "next.js build output"
	ReasonNPMCache      Reason = "npm cache"
	ReasonSetuptools    Reason = "setuptools build output"
	ReasonLegacyPrune   Reason = "vendored/build dir" // legacy name-only hint, see Pruned
)

// Verdict is the outcome of classifying a file or directory: the reason, or the
// zero value when there is no evidence and the path is in scope.
type Verdict struct {
	Reason Reason
}

// None reports that no evidence was found: the path is in scope.
func (v Verdict) None() bool { return v.Reason == "" }

// ExcludableUnderCap reports whether a Semgrep run leaves a file out of the
// target set on this evidence even when it is within MaxFileBytes. Only what
// the engine has always left out (a minified bundle) and the vendored
// libraries that make a run time out on code the project did not write count.
// A generated or compiled file under the cap is still scanned: excluding more
// than before would weaken detection.
func (v Verdict) ExcludableUnderCap() bool {
	return v.Reason == ReasonMinified || v.Reason == ReasonVendored
}

const (
	headBytes     = 64 * 1024
	tailBytes     = 2 * 1024
	maxParseBytes = 16 << 20
)

// lockfileCheck decides whether the content of a file with a lockfile's exact
// name is that lockfile's format. head is the start of the file; whole reads
// the rest when the format needs a parse.
type lockfileCheck func(head []byte, whole func() ([]byte, bool)) bool

func jsonHasKeys(keys ...string) lockfileCheck {
	return func(_ []byte, whole func() ([]byte, bool)) bool {
		data, ok := whole()
		if !ok {
			return false
		}
		var obj map[string]json.RawMessage
		if json.Unmarshal(data, &obj) != nil {
			return false
		}
		for _, k := range keys {
			if _, ok := obj[k]; !ok {
				return false
			}
		}
		return true
	}
}

func headMatches(re *regexp.Regexp) lockfileCheck {
	return func(head []byte, _ func() ([]byte, bool)) bool { return re.Match(head) }
}

var (
	reYarnLock   = regexp.MustCompile(`(?m)^(# yarn lockfile v1$|__metadata:\n\s+version: )`)
	rePnpmLock   = regexp.MustCompile(`(?m)^lockfileVersion:`)
	rePoetryLock = regexp.MustCompile(`(?m)^# This file is automatically @generated by Poetry|^\[\[package\]\]`)
	reCargoLock  = regexp.MustCompile(`(?m)^version = \d+\n|^\[\[package\]\]`)
	reGoSum      = regexp.MustCompile(`^(\S+ \S+ h1:[A-Za-z0-9+/=]+\n(\S+ \S+/go\.mod h1:[A-Za-z0-9+/=]+\n)?)`)
	reGemLock    = regexp.MustCompile(`(?m)^(GEM|GIT|PATH|PLATFORMS|DEPENDENCIES|BUNDLED WITH)$`)
	reMixLock    = regexp.MustCompile(`^%\{"`)
	rePubLock    = regexp.MustCompile(`(?m)^packages:\n|^# Generated by pub`)
	rePodLock    = regexp.MustCompile(`(?m)^PODS:$`)
	reGradleLock = regexp.MustCompile(`^# This is a Gradle generated file for dependency locking\.`)
	rePdmLock    = regexp.MustCompile(`(?m)^\[metadata\]\n`)
	reUvLock     = regexp.MustCompile(`(?m)^version = \d+\n|^\[\[package\]\]`)
	reBunLock    = regexp.MustCompile(`^#!/usr/bin/env bun\nbun-lockfile-format-v`)
)

// lockfiles maps a package manager's exact lockfile name to the check its
// content must pass. The name alone never makes a file a lockfile.
var lockfiles = map[string]lockfileCheck{
	"package-lock.json":   jsonHasKeys("lockfileVersion"),
	"npm-shrinkwrap.json": jsonHasKeys("lockfileVersion"),
	"yarn.lock":           headMatches(reYarnLock),
	"pnpm-lock.yaml":      headMatches(rePnpmLock),
	"bun.lockb":           headMatches(reBunLock),
	"deno.lock":           jsonHasKeys("version"),
	"poetry.lock":         headMatches(rePoetryLock),
	"Pipfile.lock":        jsonHasKeys("_meta", "default"),
	"pdm.lock":            headMatches(rePdmLock),
	"uv.lock":             headMatches(reUvLock),
	"Cargo.lock":          headMatches(reCargoLock),
	"go.sum":              headMatches(reGoSum),
	"composer.lock":       jsonHasKeys("content-hash", "packages"),
	"Gemfile.lock":        headMatches(reGemLock),
	"mix.lock":            headMatches(reMixLock),
	"pubspec.lock":        headMatches(rePubLock),
	"Podfile.lock":        headMatches(rePodLock),
	"packages.lock.json":  jsonHasKeys("version", "dependencies"),
	"gradle.lockfile":     headMatches(reGradleLock),
	"flake.lock":          jsonHasKeys("nodes", "root", "version"),
}

// IsLockfileName reports whether base is a package manager's exact lockfile
// name. It is a candidate test, never evidence (ClassifyFile reads the
// content).
func IsLockfileName(base string) bool {
	_, ok := lockfiles[base]
	return ok
}

// Generated says why the file at rel is a declared generated artifact by NAME
// ALONE: "lockfile", "minified" or "source map", or "" for every other file.
//
// Deprecated: a name is not evidence (decision D6'). It is kept so analyzers
// that have not moved to ClassifyFile still compile and keep their earlier
// behaviour; the Semgrep analyzer does not call it.
func Generated(rel string) string {
	base := path.Base(strings.ReplaceAll(rel, `\`, "/"))
	lower := strings.ToLower(base)
	switch {
	case IsLockfileName(base):
		return "lockfile"
	case strings.HasSuffix(lower, ".min.js"), strings.HasSuffix(lower, ".min.css"):
		return "minified"
	case strings.HasSuffix(lower, ".map"):
		return "source map"
	}
	return ""
}

// readHead reads up to n bytes from the start of the file.
func readHead(f *os.File, n int) []byte {
	buf := make([]byte, n)
	got, _ := io.ReadFull(f, buf)
	return buf[:got]
}

// readTail reads up to n bytes from the end of a file of the given size.
func readTail(f *os.File, size int64, n int) []byte {
	if size <= int64(n) {
		return nil
	}
	buf := make([]byte, n)
	got, _ := f.ReadAt(buf, size-int64(n))
	return buf[:got]
}

// ClassifyFile classifies the regular file at abs, whose path relative to the
// scan root is rel and whose size is size. It returns the zero Verdict when
// there is no evidence. It never follows or opens anything but abs.
func ClassifyFile(abs, rel string, size int64) Verdict {
	base := path.Base(strings.ReplaceAll(rel, `\`, "/"))
	ext := strings.ToLower(path.Ext(base))
	f, err := os.Open(abs)
	if err != nil {
		return Verdict{}
	}
	defer f.Close()

	whole := func() ([]byte, bool) {
		if size > maxParseBytes {
			return nil, false
		}
		if _, err := f.Seek(0, io.SeekStart); err != nil {
			return nil, false
		}
		data, err := io.ReadAll(io.LimitReader(f, maxParseBytes+1))
		if err != nil || len(data) > maxParseBytes {
			return nil, false
		}
		return data, true
	}

	if check, ok := lockfiles[base]; ok {
		head := readHead(f, headBytes)
		if check(head, whole) {
			return Verdict{ReasonLockfile}
		}
		return Verdict{}
	}
	if ext == ".map" {
		if data, ok := whole(); ok && isSourceMap(data) {
			return Verdict{ReasonSourceMap}
		}
		return Verdict{}
	}
	if size == 0 {
		return Verdict{}
	}
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		return Verdict{}
	}
	head := readHead(f, headBytes)
	if bytes.IndexByte(head, 0) >= 0 {
		// Binary content is not source of any kind: the analyzers record it
		// themselves (not text), and it carries no evidence here.
		return Verdict{}
	}
	jsLike := jsFamily[ext] || ext == ".css"
	if jsLike && isMinified(head) {
		return Verdict{ReasonMinified}
	}
	if jsFamily[ext] && isVendoredBanner(head, size) {
		return Verdict{ReasonVendored}
	}
	if hasGeneratorHeader(head) {
		return Verdict{ReasonGenerated}
	}
	if jsLike && isCompiledOutput(head, readTail(f, size, tailBytes)) {
		return Verdict{ReasonCompiled}
	}
	return Verdict{}
}

// jsFamily are the extensions the minified, vendored and compiled checks read.
var jsFamily = map[string]bool{
	".js": true, ".jsx": true, ".cjs": true, ".mjs": true, ".ts": true, ".tsx": true,
	".cts": true, ".mts": true, ".es6": true,
}

// isSourceMap reports whether data is a version-3 source map: a JSON object
// with "version": 3 and a string "mappings".
func isSourceMap(data []byte) bool {
	var m struct {
		Version  json.Number     `json:"version"`
		Mappings json.RawMessage `json:"mappings"`
	}
	if json.Unmarshal(data, &m) != nil || m.Version.String() != "3" {
		return false
	}
	return len(m.Mappings) > 0 && m.Mappings[0] == '"'
}

// Minified thresholds. Measured on real code (FENDIX_SCOPE_CORPUS in
// corpus_test.go reruns it): 26 272 JavaScript, TypeScript and CSS files, the
// 25 234 under node_modules of a Next.js project and those of juice-shop, gogs
// and WebGoat; and 1 175 first-party files, the Next.js project's own source,
// the engine's Go and Python tree, juice-shop's own routes, libs and tests. The
// first-party files' longest average line is 230 bytes (prose in a documentation
// component) and every one has more than 40 normal lines, so a file is minified
// only when at least 90% of the bytes it holds lie in lines over
// minifiedLongLine bytes, those lines hold at least minifiedMinLongBytes, one
// byte in minifiedSyntaxOneIn of them is ; { } ( ) or =, and it has no more than
// minifiedMaxShortLines non-blank ordinary lines (a licence banner and a
// source-map comment). Of the first-party files two are flagged, and both are
// real minified libraries (dat.gui.min.js, stats.min.js); of the 105 files in
// the three application trees whose name says min, all but five are flagged, and
// those are four multi-line minified stylesheets and a 3 KB file; the
// syntax-density condition removes 8 data and prose files the line statistics
// alone flagged. underscore-min.js, ace.js, three.js and the pdf.js build
// (openjpeg_nowasm_fallback.js, the 3-timeouts file of sre3-03) are flagged.
//
// A file that is one huge base64 line among hundreds of code lines is not
// minified: the ordinary lines keep it in scope.
const (
	minifiedLongLine      = 250
	minifiedMinLongBytes  = 1024
	minifiedMaxShortLines = 40
	minifiedSyntaxOneIn   = 20
)

func isMinified(head []byte) bool {
	total := len(head)
	if total < minifiedMinLongBytes {
		return false
	}
	longBytes, short, syntax := 0, 0, 0
	for len(head) > 0 {
		line := head
		if i := bytes.IndexByte(head, '\n'); i >= 0 {
			line, head = head[:i], head[i+1:]
		} else {
			head = nil
		}
		n := len(bytes.TrimRight(line, "\r"))
		switch {
		case n > minifiedLongLine:
			longBytes += n
			for _, c := range line {
				switch c {
				case ';', '{', '}', '(', ')', '=':
					syntax++
				}
			}
		case n > 0:
			short++
			if short > minifiedMaxShortLines {
				return false
			}
		}
	}
	// Code, not prose or data: at least one byte in twenty of the long lines is
	// ; { } ( ) or =, which minified code is full of (15-25%) and prose has none
	// of.
	return longBytes >= minifiedMinLongBytes && longBytes*10 >= total*9 && syntax*minifiedSyntaxOneIn >= longBytes
}

// leadingComment returns the text of the comment a source file opens with
// (after a byte order mark and blank lines): one /* ... */ block, or the run
// of // and # lines, at most 4 KiB. "" when the file opens with code.
func leadingComment(head []byte) string {
	s := strings.TrimLeft(string(bytes.TrimPrefix(head, []byte("\xef\xbb\xbf"))), " \t\r\n")
	if len(s) > 4096 {
		s = s[:4096]
	}
	switch {
	case strings.HasPrefix(s, "/*"):
		if i := strings.Index(s, "*/"); i >= 0 {
			return s[:i+2]
		}
		return s
	case strings.HasPrefix(s, "//"), strings.HasPrefix(s, "#"):
		var b strings.Builder
		for _, line := range strings.Split(s, "\n") {
			t := strings.TrimSpace(line)
			if !strings.HasPrefix(t, "//") && !strings.HasPrefix(t, "#") {
				break
			}
			b.WriteString(t)
			b.WriteByte('\n')
		}
		return b.String()
	}
	return ""
}

// Vendored libraries (decision D6', redteam4-d6-01, DE4-01). A file is a
// vendored library only when its CONTENT identifies one of the libraries below,
// not when it merely says so or mentions one. Three things must all hold:
//
//  1. the file opens with a comment whose subject IS the library: the comment,
//     stripped of its decoration, begins with the library's own name and a
//     version ("jQuery v3.6.0 | (c) OpenJS Foundation", "Bootstrap v3.1.1",
//     "Lodash <https://lodash.com/>"). A first-party header that mentions
//     jQuery, Socket.IO or lodash, or a /*! banner with any name and a semantic
//     version, is not that;
//  2. the file's body is that library: the library's own identifier (jQuery,
//     hljs, THREE, ...) occurs at least vendorBodyHits times after the banner,
//     which a file that is not the library has no reason to do;
//  3. the file is as big as a library is (vendorMinBytes) and its body does not
//     read an HTTP request or start a web server, which no library in the table
//     does and application code that carries a copied banner does.
//
// A library not in the table, a banner that is only a name, and a file that
// fails any of the three stay in scope: uncertain files are in scope. The
// remaining forgery, a first-party file that copies a known library's banner,
// its identifier and its size and keeps its own request handling out of the
// first 64 KiB, is the same trust a generator header carries, and like it is
// listed by name in the report. The table is what the corpus measurement found
// (FENDIX_SCOPE_CORPUS): jQuery, Bootstrap and the others below, and the
// pdf.js, three.js, ace and highlight.js builds that made Semgrep time out
// (sre3-03).
type vendorLib struct {
	name string
	// subject must match the start of the banner text (normalised by
	// bannerText), so the library is the banner's subject, not a mention.
	subject *regexp.Regexp
	// body is the library's own identifier, counted after the banner.
	body *regexp.Regexp
}

const (
	// vendorBodyHits is how many times the library's identifier occurs in the
	// first headBytes of the file after its banner.
	vendorBodyHits = 3
	// vendorMinBytes is the smallest size a vendored library is taken to be.
	// The smallest table library (a minified Zepto, Hammer.js) is about 25 KB.
	vendorMinBytes = 8 << 10
)

func lib(name, subject, body string) vendorLib {
	return vendorLib{name, regexp.MustCompile(`(?i)^(?:@(?:license|preserve) )?(?:` + subject + `)`), regexp.MustCompile(body)}
}

const ver = `v?\d+\.\d+`

var vendorLibraries = []vendorLib{
	lib("jquery", `jQuery(?: JavaScript Library| UI(?: -)?| Mobile| Migrate| Validation Plugin)?,? `+ver, `(?i)jquery`),
	lib("bootstrap", `Bootstrap(?:\.js)? `+ver, `(?i)bootstrap|\.bs\.`),
	lib("underscore", `Underscore\.js `+ver, `_wrapped|_chain|(?i:underscore)`),
	lib("lodash", `Lodash\b`, `(?i)lodash`),
	lib("backbone", `Backbone\.js `+ver, `Backbone`),
	lib("moment", `moment\.js\b`, `(?i)moment`),
	lib("angular", `Angular(?:JS)? `+ver, `(?i)angular`),
	lib("react", `React(?:-?DOM)? `+ver, `(?i)react`),
	lib("vue", `Vue\.js `+ver, `Vue`),
	lib("d3", `(?:https?://d3js\.org|D3\.js) `+ver, `\bd3\b|\bd3\.`),
	lib("chart.js", `Chart\.js `+ver, `(?i)chart`),
	lib("popper", `(?:@popperjs/core|Popper\.js|Popper) `+ver, `(?i)popper`),
	lib("highlight.js", `highlight\.js `+ver, `hljs`),
	lib("hammer", `Hammer\.JS - `+ver, `Hammer`),
	lib("zepto", `Zepto `+ver, `Zepto`),
	lib("modernizr", `modernizr `+ver, `(?i)modernizr`),
	lib("handlebars", `handlebars `+ver, `Handlebars`),
	lib("select2", `Select2 `+ver, `(?i)select2`),
	lib("datatables", `DataTables `+ver, `DataTable`),
	lib("leaflet", `Leaflet `+ver, `Leaflet`),
	lib("knockout", `Knockout JavaScript library `+ver, `\bko\.`),
	lib("highcharts", `Highcharts(?: JS| Stock| Maps| Gantt)? `+ver, `Highcharts`),
	lib("socket.io", `Socket\.IO `+ver, `(?i)socket`),
	lib("three.js", `Copyright 20\d\d(?:-20\d\d)? Three\.js Authors|@author (?:mrdoob|qiao)\b`, `THREE`),
	lib("ace", `(?:\*+ ?)?BEGIN LICENSE BLOCK\b.*Ajax\.org B\.V\.`, `\bace\b`),
	lib("pdf.js", `@licstart .*Copyright 20\d\d Mozilla Foundation`, `(?i)pdf`),
}

// reRequestUse is what application code does and no table library does: read
// an HTTP request or start a web server.
var reRequestUse = regexp.MustCompile(`\b(?:req|request)\.(?:query|body|params|cookies)\b|\b(?:require\(|from )['"](?:express|koa|fastify|http|child_process)['"]`)

var (
	reCommentOpen  = regexp.MustCompile(`^(?:/\*+!?|//!?|#!?)\s*`)
	reCommentDeco  = regexp.MustCompile(`(?m)^\s*(?:\*+|//+!?|#+)\s?`)
	reCommentClose = regexp.MustCompile(`\*+/\s*$`)
	reSpaces       = regexp.MustCompile(`\s+`)
)

// bannerText is a leading comment as plain text: its comment markers and the
// decoration at the start of each line removed, spaces collapsed.
func bannerText(c string) string {
	c = strings.TrimSpace(c)
	c = reCommentOpen.ReplaceAllString(c, "")
	c = reCommentClose.ReplaceAllString(c, "")
	c = reCommentDeco.ReplaceAllString(c, "")
	return strings.TrimSpace(reSpaces.ReplaceAllString(c, " "))
}

// isVendoredBanner reports whether head, the start of a file of the given
// size, is a known vendored library (see vendorLibraries for the three
// conditions).
func isVendoredBanner(head []byte, size int64) bool {
	if size < vendorMinBytes {
		return false
	}
	c := leadingComment(head)
	if c == "" {
		return false
	}
	text := bannerText(c)
	body := head
	if i := bytes.Index(head, []byte(c)); i >= 0 {
		body = head[i+len(c):]
	}
	for _, l := range vendorLibraries {
		if !l.subject.MatchString(text) {
			continue
		}
		if len(l.body.FindAllIndex(body, vendorBodyHits)) < vendorBodyHits {
			continue
		}
		return !reRequestUse.Match(body)
	}
	return false
}

var (
	reGoGenerated = regexp.MustCompile(`(?m)^// Code generated .* DO NOT EDIT\.?\s*$`)
	reAtGenerated = regexp.MustCompile(`(^|[\s/*#;])@generated([\s:/*]|$)`)
	reDoNotEdit   = regexp.MustCompile(`(?i)\bdo not (?:edit|modify)\b`)
	reGenerated   = regexp.MustCompile(`(?i)\b(?:auto-?generated|automatically generated|generated (?:file|code|by)|code generated|this file (?:is|was) generated)\b`)
	reGeneratedBy = regexp.MustCompile(`(?i)\bgenerated by [A-Za-z0-9_.\-]+(?: [A-Za-z0-9_.\-]+)? v?\d+\.\d+`)
	reProtobuf    = regexp.MustCompile(`Generated by the protocol buffer compiler|protoc-gen-[a-z0-9-]+|source: [^\s]+\.proto`)
	reOtherGen    = regexp.MustCompile(`(?i)Autogenerated by Thrift Compiler|OpenAPI Generator|swagger-codegen|auto generated by the swagger code generator|GENERATED CODE -- DO NOT EDIT`)
)

// generatorHeaderLines bounds how far into a file a generator header is looked
// for: the header comment of every generator named above is the first lines.
const generatorHeaderLines = 25

// hasGeneratorHeader reports whether the first lines of a file are a generator's
// header. Only comment lines count, so a line of code that mentions "generated"
// is not evidence.
func hasGeneratorHeader(head []byte) bool {
	text := string(bytes.TrimPrefix(head, []byte("\xef\xbb\xbf")))
	var comments strings.Builder
	inBlock := false
	for i, line := range strings.SplitN(text, "\n", generatorHeaderLines+1) {
		if i >= generatorHeaderLines {
			break
		}
		t := strings.TrimSpace(line)
		switch {
		case inBlock:
			comments.WriteString(t)
			comments.WriteByte('\n')
			if strings.Contains(t, "*/") {
				inBlock = false
			}
		case strings.HasPrefix(t, "/*"):
			comments.WriteString(t)
			comments.WriteByte('\n')
			inBlock = !strings.Contains(t, "*/")
		case strings.HasPrefix(t, "//"), strings.HasPrefix(t, "#"), strings.HasPrefix(t, "--"), strings.HasPrefix(t, ";"), strings.HasPrefix(t, "<!--"):
			comments.WriteString(t)
			comments.WriteByte('\n')
		case t == "":
		default:
			// Code. A generator's header precedes it, except a Python coding line
			// or shebang, which are comments anyway; stop at the first code line.
			i = generatorHeaderLines
		}
		if i >= generatorHeaderLines {
			break
		}
	}
	c := comments.String()
	if c == "" {
		return false
	}
	switch {
	case reGoGenerated.MatchString(c), reProtobuf.MatchString(c), reOtherGen.MatchString(c):
		return true
	case reAtGenerated.MatchString(c):
		return true
	case reDoNotEdit.MatchString(c) && reGenerated.MatchString(c):
		return true
	case reGeneratedBy.MatchString(c):
		return true
	}
	return false
}

var (
	reSourceMapRef = regexp.MustCompile(`(?m)^\s*(?://|/\*)[#@]\s*sourceMappingURL=\S+`)
	reWebpackBoot  = regexp.MustCompile(`// webpackBootstrap`)
)

func isCompiledOutput(head, tail []byte) bool {
	if reWebpackBoot.Match(head) {
		return true
	}
	if len(tail) == 0 {
		tail = head
	}
	return reSourceMapRef.Match(tail)
}
